fn fail(label: String) -> Box<dyn std::error::Error> {
    Box::new(std::io::Error::other(label))
}

pub(super) fn replay(store: &Store) -> TestResult {
    for (phase, key, raw) in GOLDEN_JOURNAL {
        let payload: serde_json::Value = match serde_json::from_str(raw) {
            Ok(value) => value,
            Err(error) => {
                return Err(fail(format!("golden journal {phase}/{key}: {error}")));
            }
        };
        let mut batch = store.write_batch();
        if let Err(error) = batch.journal_done(phase, key, &payload) {
            return Err(fail(format!("golden journal {phase}/{key}: {error}")));
        }
        if let Err(error) = batch.commit() {
            return Err(fail(format!("golden journal commit: {error}")));
        }
    }
    Ok(())
}
